(function () {
  const content = document.getElementById('patient-content');
  const patient = DentalMock.patient('pat_maria_quispe');
  const money = DentalMock.money;
  const state = { view: new URLSearchParams(location.search).get('view') || 'home' };
  const appointment = DentalMock.appointmentsFor(patient.id)[0] || { time: '10:30', end: '11:30', type: 'Evaluación integral', status: 'Confirmada' };
  function topbar(title, subtitle) { document.getElementById('patient-topbar').innerHTML = renderTopbar(title, subtitle); }
  function layout() {
    document.querySelectorAll('#patient-nav button').forEach(btn => { btn.classList.toggle('active', btn.dataset.view === state.view); btn.onclick = () => { state.view = btn.dataset.view; history.replaceState(null, '', `paciente.html?view=${state.view}`); layout(); }; });
    if (state.view === 'home') home(); if (state.view === 'appointments') appointments(); if (state.view === 'treatment') treatment(); if (state.view === 'documents') documents(); if (state.view === 'payments') payments();
  }
  function heading(title, text) { return `<div class="page-heading"><div><div class="eyebrow">Mi espacio · ${DentalMock.data.organization.site}</div><h1>${title}</h1><p>${text}</p></div><span class="chip">Datos ficticios</span></div>`; }
  function home() { topbar('Hola, María', 'Tu atención en Sillar Dental'); content.innerHTML = heading('Tu sonrisa, paso a paso.', 'Aquí encontrarás tu próxima cita, avances, documentos y pagos en un solo lugar.') + `<div class="grid-3"><div class="card kpi"><div class="label">Próxima cita</div><div class="value">${appointment.time}</div><div class="trend">${appointment.type} · 24 jul</div></div><div class="card kpi"><div class="label">Avance de tu plan</div><div class="value">${patient.planProgress}%</div><div class="progress" style="margin-top:10px"><span style="width:${patient.planProgress}%"></span></div></div><div class="card kpi"><div class="label">Saldo pendiente</div><div class="value">${money(patient.balance)}</div><div class="trend">3 cuotas programadas</div></div></div><div class="dashboard-grid"><section class="card panel"><div class="panel-head"><h2>Tu próxima cita</h2><a class="btn btn-soft btn-small" href="paciente.html?view=appointments">Ver mis citas</a></div><div class="patient-banner" style="background:var(--blue-soft);margin:0"><div class="patient-banner-main"><span class="avatar teal">CV</span><div><h2>Evaluación integral</h2><p>Jue 24 de julio · 10:30 a. m. · Dra. Camila Valdivia</p></div></div>${statusChip(appointment.status)}</div><div class="row-between" style="margin-top:18px"><span class="tiny">Av. Los Arces 418 · Yanahuara</span><button class="btn btn-secondary btn-small" data-action="confirm">Confirmar asistencia</button></div></section><section class="card panel"><div class="panel-head"><h2>Actividad reciente</h2><span class="tiny">Últimos 30 días</span></div><div class="alert-list"><div class="alert">${icon('file-check')}<div><strong>Informe radiográfico disponible</strong><span>Puedes revisarlo en Documentos.</span></div></div><div class="alert">${icon('wallet')}<div><strong>Adelanto registrado</strong><span>Tu crédito de ${money(300)} está aplicado.</span></div></div><div class="alert">${icon('calendar')}<div><strong>Control recomendado</strong><span>Agenda tu siguiente revisión.</span></div></div></div></section></div>`; bindActions(); }
  function appointments() { topbar('Mis citas', 'Consulta, confirma o solicita cambios'); content.innerHTML = heading('Tus citas', 'La clínica confirmará el recurso antes de cerrar cualquier cambio.') + `<div class="card panel"><div class="panel-head"><h2>Próximas</h2><a class="btn btn-primary btn-small" href="reservar.html">Solicitar nueva cita ${icon('plus')}</a></div><div class="agenda-list"><div class="agenda-item"><div class="agenda-time">24 JUL<br><strong>10:30</strong></div><div><strong>Evaluación integral</strong><small>Dra. Camila Valdivia · Sillón 1 · Yanahuara</small></div>${statusChip('Confirmada')}</div><div class="agenda-item"><div class="agenda-time">31 JUL<br><strong>16:00</strong></div><div><strong>Revisión de plan</strong><small>Dra. Camila Valdivia · Duración estimada 45 min</small></div>${statusChip('Por confirmar')}</div></div></div><div class="card panel" style="margin-top:18px"><div class="panel-head"><h2>Antes de venir</h2></div><div class="grid-3"><div><span class="eyebrow">01</span><h3>Trae tu documento</h3><p class="muted tiny">Recepción verificará tu identidad y datos.</p></div><div><span class="eyebrow">02</span><h3>Comparte antecedentes</h3><p class="muted tiny">Puedes actualizar alergias desde recepción.</p></div><div><span class="eyebrow">03</span><h3>Llega con 10 min</h3><p class="muted tiny">Así revisamos formularios sin apuro.</p></div></div></div>`; bindActions(); }
  function treatment() { topbar('Mi tratamiento', 'Lo que encontramos y lo que proponemos'); content.innerHTML = heading('Un plan que puedes entender.', 'Tu plan separa los hallazgos observados de los tratamientos propuestos.') + `<div class="clinic-grid"><div class="stack"><section class="card panel"><div class="panel-head"><div><h2>Plan v2 · Aceptado parcialmente</h2><span class="tiny">Actualizado 22 jul 2026 · Dra. Camila Valdivia</span></div>${statusChip('Aceptado parcialmente')}</div><div class="stack">${DentalMock.data.plan.items.map(item => `<div class="agenda-item"><div class="avatar ${item.status === 'Propuesto' ? 'amber' : 'teal'}">${item.tooth}</div><div><strong>${item.name}</strong><small>Pieza ${item.tooth} · ${item.category} · Prioridad ${item.priority}</small></div><div style="text-align:right"><strong>${money(item.amount)}</strong><small>${item.status}</small></div></div>`).join('')}</div></section><section class="card panel"><div class="panel-head"><h2>Línea de tiempo</h2><span class="tiny">Evolución documentada</span></div><div class="timeline"><div class="timeline-item"><span class="date">22 jul 2026</span><span class="timeline-dot"></span><div class="body"><strong>Evaluación y diagnóstico</strong><p>Hallazgo registrado en pieza 16. Radiografía e informe disponibles.</p></div></div><div class="timeline-item"><span class="date">22 jul 2026</span><span class="timeline-dot" style="background:var(--teal)"></span><div class="body"><strong>Presupuesto aceptado</strong><p>Plan de pagos con adelanto y tres cuotas.</p></div></div><div class="timeline-item"><span class="date">Próximo</span><span class="timeline-dot" style="background:var(--amber)"></span><div class="body"><strong>Restauración pieza 16</strong><p>Por agendar en una cita de 60 minutos.</p></div></div></div></section></div><aside class="card panel"><div class="panel-head"><h2>Tu presupuesto</h2></div><div class="row-between"><span class="muted">Aceptado</span><strong class="money">${money(3780)}</strong></div><div class="divider" style="margin:18px 0"></div><div class="row-between"><span class="muted">Adelanto</span><strong>${money(300)}</strong></div><div class="row-between" style="margin-top:8px"><span class="muted">Cuotas pendientes</span><strong>${money(3480)}</strong></div><a class="btn btn-primary" href="paciente.html?view=payments" style="width:100%;margin-top:22px">Ver plan de pagos ${icon('arrow')}</a></aside></div>`; }
  function documents() { topbar('Documentos y resultados', 'Contenido publicado por tu equipo clínico'); const docs = DentalMock.documentsFor(patient.id).filter(d => d.visibility === 'Publicado'); content.innerHTML = heading('Resultados que puedes consultar.', 'La clínica publica cada documento después de revisarlo y asociarlo a tu atención.') + `<div class="grid-2">${docs.map(d => `<article class="card panel"><div class="row-between"><div class="row"><span class="avatar teal">${icon(d.icon)}</span><div><strong>${d.name}</strong><div class="tiny">${d.type} · ${d.date}</div></div></div>${statusChip(d.status)}</div>${d.file ? `<img class="doc-preview" src="${d.file}" alt="Vista previa de ${d.name}">` : `<div class="empty doc-preview-placeholder">${icon(d.icon)}<span>Vista previa protegida</span></div>`}<div class="divider" style="margin:18px 0"></div><div class="row-between"><span class="tiny">Versión final · acceso protegido</span><button class="btn btn-secondary btn-small" data-action="open-doc" data-doc="${d.id}">Abrir ${icon('arrow')}</button></div></article>`).join('')}</div><div class="card panel" style="margin-top:18px;background:var(--blue-soft)"><div class="row"><span class="avatar">i</span><div><strong>¿No ves un archivo?</strong><p class="tiny" style="margin:3px 0 0">Puede estar aún en revisión clínica. La clínica te avisará cuando sea publicable.</p></div></div></div>`; bindActions(); }
  function payments() { topbar('Pagos y cuotas', 'Tu cuenta explicada con claridad'); const installments = DentalMock.installmentsFor(patient.id); content.innerHTML = heading('Tu cuenta', 'El saldo se calcula a partir de cargos, adelantos y aplicaciones confirmadas.') + `<div class="grid-3"><div class="card kpi"><div class="label">Presupuesto aceptado</div><div class="value">${money(3780)}</div><div class="trend">Plan v2 · 22 jul 2026</div></div><div class="card kpi"><div class="label">Adelanto</div><div class="value">${money(300)}</div><div class="trend">Confirmado · Yape / QR</div></div><div class="card kpi"><div class="label">Saldo pendiente</div><div class="value">${money(3480)}</div><div class="trend">Próximo vencimiento 15 ago</div></div></div><div class="dashboard-grid"><section class="card panel"><div class="panel-head"><h2>Plan de cuotas</h2><button class="btn btn-primary btn-small" data-action="pay">Pagar cuota</button></div><div class="stack">${installments.map(i => `<div class="agenda-item"><div class="avatar ${i.status === 'Vencida' ? 'terracotta' : 'teal'}">${i.number}</div><div><strong>Cuota ${i.number}</strong><small>Vence ${i.due}</small></div><div style="text-align:right"><strong>${money(i.amount)}</strong><small>${statusChip(i.status)}</small></div></div>`).join('')}</div></section><section class="card panel"><div class="panel-head"><h2>Movimientos</h2></div><div class="stack">${DentalMock.paymentsFor(patient.id).map(p => `<div class="row-between"><div><strong style="font-size:.82rem">${p.description}</strong><div class="tiny">${p.date} · ${p.method}</div></div><strong>${money(p.amount)}</strong></div>`).join('')}</div></section></div>`; bindActions(); }
  function bindActions() { content.querySelectorAll('[data-action]').forEach(el => el.onclick = () => { if (el.dataset.action === 'confirm') { toast('Confirmación registrada en el prototipo.'); el.textContent = 'Asistencia confirmada'; el.classList.add('btn-soft'); } if (el.dataset.action === 'pay') toast('Pasarela simulada: no se realizó ningún cobro.'); if (el.dataset.action === 'open-doc') toast('Visor simulado · archivo protegido.'); }); }
  layout();
})();
